(function () {
  function readJsonScript(id, fallback) {
    const element = document.getElementById(id);
    if (!element) {
      return fallback;
    }
    try {
      return JSON.parse(element.textContent || '');
    } catch (_error) {
      return fallback;
    }
  }

  function getCookie(name) {
    const prefix = `${name}=`;
    return document.cookie
      .split(';')
      .map((cookie) => cookie.trim())
      .find((cookie) => cookie.startsWith(prefix))
      ?.slice(prefix.length) || '';
  }

  async function apiRequest(path, options, csrfToken) {
    const settings = options || {};
    const headers = {
      Accept: 'application/json',
      ...(settings.headers || {}),
    };
    const method = settings.method || 'GET';
    let body = settings.body;

    if (settings.json !== undefined) {
      headers['Content-Type'] = 'application/json';
      body = JSON.stringify(settings.json);
    }

    if (method !== 'GET') {
      headers['X-CSRFToken'] = csrfToken || '';
    }

    const response = await fetch(path, {
      method,
      headers,
      body,
      credentials: 'same-origin',
    });

    if (response.status === 204) {
      return null;
    }

    const contentType = response.headers.get('content-type') || '';
    const payload = contentType.includes('application/json')
      ? await response.json()
      : await response.text();

    if (!response.ok) {
      const detail = typeof payload === 'object' && payload !== null
        ? payload.detail
          || payload.message
          || payload.error
          || Object.values(payload).flat().join(' ')
        : payload;
      throw new Error(detail || `Request failed with status ${response.status}`);
    }

    return payload;
  }

  let googleMapsContextualViewPromise = null;

  function getGoogleMapsWidgetToken(contextJson) {
    const grounding = contextJson?.google_maps_grounding;
    const tokens = grounding?.widget_context_tokens;
    if (Array.isArray(tokens)) {
      return tokens.find((token) => typeof token === 'string' && token.trim()) || '';
    }
    return typeof grounding?.widget_context_token === 'string'
      ? grounding.widget_context_token.trim()
      : '';
  }

  function loadGoogleMapsContextualView(apiKey) {
    const normalizedApiKey = String(apiKey || '').trim();
    if (!normalizedApiKey) {
      return Promise.reject(new Error('Missing Google Maps browser API key.'));
    }
    if (window.google?.maps?.importLibrary) {
      return Promise.resolve();
    }
    if (googleMapsContextualViewPromise) {
      return googleMapsContextualViewPromise;
    }

    googleMapsContextualViewPromise = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(normalizedApiKey)}&v=alpha&libraries=places`;
      script.async = true;
      script.defer = true;
      script.onload = resolve;
      script.onerror = () => {
        googleMapsContextualViewPromise = null;
        script.remove();
        reject(new Error('Unable to load Google Maps widget.'));
      };
      document.head.appendChild(script);
    });
    return googleMapsContextualViewPromise;
  }

  function renderGoogleMapsGroundingWidget(contextJson, cards, options) {
    const settings = options || {};
    const contextToken = getGoogleMapsWidgetToken(contextJson);
    const apiKey = String(settings.apiKey || '').trim();
    if (!contextToken || !cards || !apiKey) {
      return;
    }

    const card = document.createElement('div');
    card.className = settings.cardClassName || 'clancy-agent-card clancy-google-maps-widget';
    const label = document.createElement('div');
    label.className = settings.labelClassName || 'clancy-card-label';
    label.textContent = 'Map context';
    const host = document.createElement('div');
    host.className = settings.hostClassName || 'clancy-google-maps-widget-host';
    card.append(label, host);
    cards.appendChild(card);

    void loadGoogleMapsContextualView(apiKey)
      .then(async () => {
        await window.google.maps.importLibrary('places');
        const places = window.google.maps.places;
        const widget = new places.PlaceContextualElement({ contextToken });
        widget.className = settings.widgetClassName || 'clancy-google-maps-contextual';
        if (
          places.PlaceContextualListConfigElement
          && places.PlaceContextualListLayout?.COMPACT
        ) {
          const config = new places.PlaceContextualListConfigElement({
            layout: places.PlaceContextualListLayout.COMPACT,
          });
          widget.appendChild(config);
        }
        host.replaceChildren(widget);
      })
      .catch(() => {
        card.remove();
      });
  }

  window.FamilyAssistantHelpers = {
    readJsonScript,
    getCookie,
    apiRequest,
    renderGoogleMapsGroundingWidget,
  };
})();

