      showError(error);
    }
  }

  async function archiveActiveThread() {
    const thread = getActiveThread();
    if (!thread) {
      return;
    }
    if (!window.confirm(`Archive "${thread.title || 'this conversation'}"?`)) {
      return;
    }

    setStatus('Archiving conversation...');
    try {
      await apiRequest(`/api/family-agent/threads/${thread.id}/archive/`, {
        method: 'POST',
        json: {},
      });
      state.activeThreadId = null;
      await loadThreads();
      setStatus('');
    } catch (error) {
      showError(error);
    }
  }

  async function sendMessage() {
    if (state.isSending) {
      return;
    }
    const text = (elements.input?.value || '').trim();
    if (!text && state.selectedFiles.length === 0) {
      return;
    }

    state.isSending = true;
    setComposerEnabled(false);
    setStatus(`${helperName} is getting this ready...`);

    try {
      if (!state.activeThreadId) {
        const thread = await apiRequest('/api/family-agent/threads/', {
          method: 'POST',
          json: { title: 'New conversation' },
        });
        state.activeThreadId = thread.id;
      }

      const formData = new FormData();
      formData.append('thread_id', state.activeThreadId);
      formData.append('text', text);
      formData.append('context', JSON.stringify(buildMessageContext()));
      state.selectedFiles.forEach((file) => formData.append('images', file));

      const response = await apiRequest('/api/family-agent/thread/messages/', {
        method: 'POST',
        body: formData,
      });

      if (elements.input) {
        elements.input.value = '';
      }
      if (elements.imageInput) {
        elements.imageInput.value = '';
      }
      state.selectedFiles = [];
      state.pendingContext = {};
      renderSelectedImages();
      resizeComposer();
      await loadThreads(response?.thread?.id || state.activeThreadId);
      setStatus('');
    } catch (error) {
      showError(error);
    } finally {
      state.isSending = false;
      setComposerEnabled(true);
    }
  }

  function buildMessageContext() {
    return {
      ...baseContext,
      ...state.pendingContext,
      google_maps_widget_supported: true,
    };
  }

  async function runCardAction(button) {
    const kind = button.dataset.agentAction;
    const id = button.dataset.agentId;
    const verb = button.dataset.agentVerb;
    if (!kind || !id || !verb) {
      return;
    }

    const path = kind === 'proposal'
      ? `/api/family-agent/proposals/${id}/${verb}/`
      : `/api/family-agent/memory-suggestions/${id}/${verb}/`;

    button.disabled = true;
    setStatus(verb === 'approve' ? 'Approving...' : 'Rejecting...');
    try {
      await apiRequest(path, { method: 'POST', json: {} });
      await loadMessages();
      setStatus('');
    } catch (error) {
      button.disabled = false;
      showError(error);
    }
  }

  function renderStarters() {
    if (!elements.starters) {
      return;
    }
    elements.starters.replaceChildren();
    starterPrompts.forEach((starter, index) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'btn btn-outline-primary btn-sm clancy-starter';
      button.dataset.starterIndex = String(index);
      const icon = document.createElement('i');
      icon.className = `bi ${starter.icon || 'bi-stars'} me-1`;
      icon.setAttribute('aria-hidden', 'true');
      button.append(icon, document.createTextNode(starter.label || starter.prompt || 'Start'));
      elements.starters.appendChild(button);
    });
  }

  function renderThreads() {
    if (!elements.threadList) {
      return;
    }
    elements.threadList.replaceChildren();
    if (state.threads.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'text-muted text-center py-4';
      empty.textContent = 'No conversations yet';
      elements.threadList.appendChild(empty);
      return;
    }
    state.threads.forEach((thread) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = `clancy-thread-item${thread.id === state.activeThreadId ? ' active' : ''}`;
      button.dataset.threadId = thread.id;
      const title = document.createElement('span');
      title.className = 'clancy-thread-title';
      title.textContent = thread.title || 'New conversation';
      const meta = document.createElement('span');
      meta.className = 'clancy-thread-meta';
      meta.textContent = formatDate(thread.updated_at);
      button.append(title, meta);
      elements.threadList.appendChild(button);
    });
    updateActiveTitle();
  }

  function renderMessages() {
    if (!elements.messages) {
      return;
    }
    elements.messages.replaceChildren();
    if (state.messages.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'clancy-empty';
      const inner = document.createElement('div');
      const icon = document.createElement('i');
      icon.className = 'bi bi-chat-square-text';
      icon.setAttribute('aria-hidden', 'true');
      icon.style.fontSize = '2rem';
      icon.style.opacity = '0.35';
      const text = document.createElement('p');
      text.className = 'mt-2 mb-0';
      text.textContent = `Start a conversation with ${helperName}.`;
      inner.append(icon, text);
      if (initialPrompt.trim()) {
        const card = document.createElement('button');
        card.type = 'button';
        card.className = 'clancy-prompt-card';
        card.dataset.suggestionPrompt = initialPrompt;
        const label = document.createElement('span');
        label.className = 'clancy-prompt-card-label';
        label.textContent = 'Suggested prompt';
        const promptText = document.createElement('span');
        promptText.className = 'clancy-prompt-card-text';
        promptText.textContent = initialPrompt;
        card.append(label, promptText);
        inner.appendChild(card);
      }
      empty.appendChild(inner);
      elements.messages.appendChild(empty);
      return;
    }

    state.messages.forEach((message) => {
      const node = renderMessage(message);
      if (node) {
        elements.messages.appendChild(node);
      }
    });

    if (hasPendingResponse()) {
      elements.messages.appendChild(renderPending());
    }
    elements.messages.scrollTop = elements.messages.scrollHeight;
  }

  function renderMessage(message) {
    if (message.role === 'system') {
      return null;
    }
    const wrapper = document.createElement('article');
    wrapper.className = `clancy-message ${message.role || 'assistant'}`;

    const meta = document.createElement('div');
    meta.className = 'clancy-message-meta';
    meta.textContent = message.role === 'user' ? 'You' : helperName;

    const bubble = document.createElement('div');
    bubble.className = 'clancy-bubble';
    const text = document.createElement('div');
    text.className = 'clancy-message-text';
    const entityLinks = Array.isArray(message.entity_links) ? message.entity_links : [];
    if (message.role === 'assistant' || message.role === 'system') {
      renderFormattedMessageText(text, message.text || '', entityLinks);
    } else {
      text.textContent = message.text || '';
    }
    bubble.appendChild(text);

    wrapper.append(meta, bubble);
    const attachments = renderAttachments(message.attachments || []);
    if (attachments) {
      wrapper.appendChild(attachments);
    }

    const cards = document.createElement('div');
    cards.className = 'clancy-card-stack';
    renderRunError(message, cards);
    renderCitations(message.citations_json || [], cards, message.context_json || {});
    (message.action_suggestions || []).forEach((suggestion) => cards.appendChild(renderActionSuggestion(suggestion)));
    renderGoogleMapsGroundingWidget(message.context_json || {}, cards, {
      apiKey: googleMapsClientApiKey,
    });
    (message.proposals || []).forEach((proposal) => cards.appendChild(renderProposal(proposal)));
    (message.memory_suggestions || []).forEach((suggestion) => cards.appendChild(renderMemorySuggestion(suggestion)));
    if (cards.childElementCount > 0) {
      wrapper.appendChild(cards);
    }
    return wrapper;
  }

  function renderPending() {
    const wrapper = document.createElement('div');
    wrapper.className = 'clancy-message assistant';
    const bubble = document.createElement('div');
    bubble.className = 'clancy-bubble';
    bubble.innerHTML = `<span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>${escapeHtml(helperName)} is thinking...`;
    wrapper.appendChild(bubble);
    return wrapper;
  }

  function renderFormattedMessageText(container, value, entityLinks) {
    const rawText = String(value || '').trim();
    if (!rawText) {
      return;
    }

    const links = normalizeEntityLinks(entityLinks);
    const lines = rawText.split(/\r?\n/);
    let paragraphLines = [];
    let list = null;

    function flushParagraph() {
      if (paragraphLines.length === 0) {
        return;
      }
      const paragraph = document.createElement('p');
      appendInlineMarkdown(paragraph, paragraphLines.join(' '), links);
      container.appendChild(paragraph);
      paragraphLines = [];
    }

    function flushList() {
      if (list) {
        container.appendChild(list);
        list = null;
      }
    }

    lines.forEach((line) => {
      const trimmed = line.trim();
      if (!trimmed) {
        flushParagraph();
        flushList();
        return;
      }

      const headingMatch = trimmed.match(/^(#{1,6})\s+(.+?)\s*#*$/);
      if (headingMatch) {
        flushParagraph();
        flushList();
        const level = Math.min(headingMatch[1].length, 6);
        const heading = document.createElement(`h${level}`);
        appendInlineMarkdown(heading, headingMatch[2], links);
        container.appendChild(heading);
        return;
      }

      const unorderedMatch = trimmed.match(/^[-*]\s+(.+)$/);
      const orderedMatch = trimmed.match(/^\d+\.\s+(.+)$/);
      if (unorderedMatch || orderedMatch) {
        flushParagraph();
        const nextTag = unorderedMatch ? 'ul' : 'ol';
        if (!list || list.tagName.toLowerCase() !== nextTag) {
          flushList();
          list = document.createElement(nextTag);
        }
        const item = document.createElement('li');
        appendInlineMarkdown(item, unorderedMatch?.[1] || orderedMatch?.[1] || '', links);
        list.appendChild(item);
        return;
      }

      flushList();
      paragraphLines.push(trimmed);
    });

    flushParagraph();
    flushList();
  }

  function appendInlineMarkdown(parent, value, entityLinks) {
    const text = String(value || '');
    const pattern = /(\[\[ref:\d+\]\]|\*\*[^*]+\*\*|__[^_]+__|`[^`]+`)/g;
    let cursor = 0;
    text.replace(pattern, (match, _token, offset) => {
      if (offset > cursor) {
        appendLinkedText(parent, text.slice(cursor, offset), entityLinks);
      }
      const refMatch = match.match(/^\[\[ref:(\d+)\]\]$/);
      if (refMatch) {
        const link = entityLinks[Number(refMatch[1])];
        if (link) {
          parent.appendChild(renderInlineEntityCard(link));
        }
      } else if (match.startsWith('`')) {
        const code = document.createElement('code');
        appendLinkedText(code, match.slice(1, -1), entityLinks);
        parent.appendChild(code);
      } else {
        const strong = document.createElement('strong');
        appendLinkedText(strong, match.slice(2, -2), entityLinks);
        parent.appendChild(strong);
      }
      cursor = offset + match.length;
      return match;
    });
    if (cursor < text.length) {
      appendLinkedText(parent, text.slice(cursor), entityLinks);
    }
  }

  function renderInlineEntityCard(link) {
    const anchor = document.createElement('a');
    anchor.className = `clancy-entity-card clancy-entity-card--${link.kind || 'generic'}`;
    anchor.href = link.url;
    if (link.ownerName) {
      anchor.title = `${link.label} (${link.ownerName})`;
    }
    if (link.kind === 'event' && (link.ownerAvatarUrl || link.ownerInitials || link.ownerName)) {
      if (link.ownerAvatarUrl) {
        const avatar = document.createElement('img');
        avatar.className = 'clancy-entity-card__avatar';
        avatar.src = link.ownerAvatarUrl;
        avatar.alt = link.ownerName || link.label;
        anchor.appendChild(avatar);
      } else {
        const initials = document.createElement('span');
        initials.className = 'clancy-entity-card__initials';
        initials.textContent = link.ownerInitials || initialsFromName(link.ownerName || link.label);
        if (link.color) {
          initials.style.backgroundColor = link.color;
        }
        anchor.appendChild(initials);
      }
    }
    const kindChip = document.createElement('span');
    kindChip.className = 'clancy-entity-card__kind';
    kindChip.textContent = humanizeKind(link.kind);
    const labelSpan = document.createElement('span');
    labelSpan.className = 'clancy-entity-card__label';
    labelSpan.textContent = link.label;
    anchor.append(kindChip, labelSpan);
    return anchor;
  }

  function initialsFromName(value) {
    const parts = String(value || '').trim().split(/\s+/).filter(Boolean);
    if (parts.length === 0) {
      return '?';
    }
    if (parts.length === 1) {
      return parts[0].slice(0, 1).toUpperCase();
    }
    return `${parts[0].slice(0, 1)}${parts[parts.length - 1].slice(0, 1)}`.toUpperCase();
  }

  function humanizeKind(kind) {
    if (!kind) {
      return 'Link';
    }
    return String(kind)
      .replace(/_/g, ' ')
      .replace(/\b\w/g, (c) => c.toUpperCase());
  }

  function appendLinkedText(parent, value, entityLinks) {
    const text = String(value || '');
    if (!text || entityLinks.length === 0) {
      parent.appendChild(document.createTextNode(text));
      return;
    }

    const lowerText = text.toLowerCase();
    let cursor = 0;
    while (cursor < text.length) {
      let bestMatch = null;
      entityLinks.forEach((link) => {
        const index = lowerText.indexOf(link.labelLower, cursor);
        if (index === -1) {
          return;
        }
        if (
          bestMatch === null
          || index < bestMatch.index
          || (index === bestMatch.index && link.label.length > bestMatch.link.label.length)
        ) {
          bestMatch = { index, link };
        }
      });

      if (bestMatch === null) {
        parent.appendChild(document.createTextNode(text.slice(cursor)));
        break;
      }

      if (bestMatch.index > cursor) {
        parent.appendChild(document.createTextNode(text.slice(cursor, bestMatch.index)));
      }
      const link = document.createElement('a');
      link.className = 'clancy-entity-link';
      link.href = bestMatch.link.url;
      link.textContent = text.slice(bestMatch.index, bestMatch.index + bestMatch.link.label.length);
      parent.appendChild(link);
      cursor = bestMatch.index + bestMatch.link.label.length;
    }
  }

  function normalizeEntityLinks(value) {
    if (!Array.isArray(value)) {
      return [];
    }
    return value
      .filter((item) => item && item.label && item.url)
      .map((item) => {
        const label = String(item.label);
        return {
          kind: String(item.kind || ''),
          id: String(item.id || ''),
          label,
          labelLower: label.toLowerCase(),
          url: String(item.url),
          ownerName: String(item.owner_name || ''),
          ownerShortName: String(item.owner_short_name || ''),
          ownerInitials: String(item.owner_initials || ''),
          ownerAvatarUrl: String(item.owner_avatar_url || ''),
          color: String(item.color || ''),
        };
      });
  }

  function renderAttachments(attachments) {
    const usable = attachments.filter((attachment) => attachment.thumbnail_url || attachment.preview_url);
    if (!usable.length) {
      return null;
    }
    const container = document.createElement('div');
    container.className = 'clancy-attachments';
    usable.forEach((attachment) => {
      const link = document.createElement('a');
      link.className = 'clancy-attachment';
      link.href = attachment.preview_url || attachment.thumbnail_url;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      const image = document.createElement('img');
      image.src = attachment.thumbnail_url || attachment.preview_url;
      image.alt = attachment.original_filename || 'Attachment';
      link.appendChild(image);
      container.appendChild(link);
    });
    return container;
  }

  function renderRunError(message, cards) {
    if ((message.run_status || '').toUpperCase() !== 'FAILED' || !message.run_error_text) {
      return;
    }
    const card = document.createElement('div');
    card.className = 'clancy-agent-card clancy-error';
    card.textContent = message.run_error_text;
    cards.appendChild(card);
  }

  function renderCitations(citations, cards, contextJson) {
    if (contextJson?.google_maps_grounding?.widget_context_tokens?.length) {
      return;
    }
    if (!Array.isArray(citations) || citations.length === 0) {
      return;
    }
    const card = document.createElement('div');
    card.className = 'clancy-agent-card clancy-citations';
    const label = document.createElement('div');
    label.className = 'clancy-card-label';
    label.textContent = 'Sources';
    card.appendChild(label);
    citations.forEach((citation) => {
      if (!citation.url) {
        return;
      }
      const link = document.createElement('a');
      link.className = 'clancy-citation';
      link.href = citation.url;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.textContent = citation.title || citation.url;
      card.appendChild(link);
    });
    if (card.childElementCount > 1) {
      cards.appendChild(card);
    }
  }

  function renderActionSuggestion(suggestion) {
    const card = document.createElement('div');
    card.className = 'clancy-agent-card';
    const label = document.createElement('div');
    label.className = 'clancy-card-label';
    label.textContent = suggestion.label || 'Suggested action';
    const title = document.createElement('h3');
    title.textContent = suggestion.title || 'Suggestion';
    card.append(label, title);

    if (suggestion.summary) {
      const summary = document.createElement('p');
      summary.className = 'text-muted mb-2';
      summary.textContent = suggestion.summary;
      card.appendChild(summary);
    }

    const target = getActionSuggestionTarget(suggestion);
    if (target.supportingText) {
      const supporting = document.createElement('p');
      supporting.className = 'text-muted small mb-0';
      supporting.textContent = target.supportingText;
      card.appendChild(supporting);
    }
    if (target.imageUrl) {
      const image = document.createElement('img');
      image.src = target.imageUrl;
      image.alt = suggestion.product?.image_alt || suggestion.title || 'Suggestion image';
      image.className = 'img-fluid rounded my-2';
      card.appendChild(image);
    }

    const actions = document.createElement('div');
    actions.className = 'clancy-card-actions';
    if (target.url) {
      const link = document.createElement('a');
      link.href = target.url;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.className = 'btn btn-primary btn-sm';
      link.textContent = target.buttonLabel;
      actions.appendChild(link);
    }
    if (suggestion.prompt) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'btn btn-outline-primary btn-sm';
      button.dataset.suggestionPrompt = suggestion.prompt;
      button.textContent = 'Ask about this';
      actions.appendChild(button);
    }
    if (actions.childElementCount > 0) {
      card.appendChild(actions);
    }
    return card;
  }

  function getActionSuggestionTarget(suggestion) {
    if (suggestion.restaurant?.maps_url) {
      return {
        url: suggestion.restaurant.maps_url,
        buttonLabel: 'Open in Maps',
        supportingText: suggestion.restaurant.address || suggestion.restaurant.name || '',
      };
    }
    if (suggestion.url) {
      return {
        url: suggestion.url,
        buttonLabel: suggestion.type === 'external_scheduling_handoff' ? 'Open Calendly' : 'Open',
        supportingText: '',
      };
    }
    if (suggestion.product?.url) {
      const merchant = [suggestion.product.merchant_name, suggestion.product.merchant_domain]
        .filter(Boolean)
        .join(' / ');
      return {
        url: suggestion.product.url,
        buttonLabel: 'Open Product',
        supportingText: [merchant, suggestion.product.price_text, suggestion.product.availability_text]
          .filter(Boolean)
          .join(' · '),
        imageUrl: suggestion.product.image_url || '',
      };
    }
    return { url: '', buttonLabel: 'Open', supportingText: '' };
  }

  function renderProposal(proposal) {
    const card = document.createElement('div');
    card.className = 'clancy-agent-card';
    const header = document.createElement('div');
    header.className = 'd-flex justify-content-between align-items-start gap-2';
    const title = document.createElement('h3');
    title.textContent = proposal.summary || 'Proposal';
    const status = document.createElement('span');
    status.className = `clancy-status-pill${proposal.status === 'pending_approval' ? ' pending' : ''}`;
    status.textContent = formatStatus(proposal.status);
    header.append(title, status);
    card.appendChild(header);

    if (proposal.preview_text) {
      const preview = document.createElement('p');
      preview.className = 'text-muted mb-0';
      preview.textContent = proposal.preview_text;
      card.appendChild(preview);
    }
    if (proposal.error_text) {
      const error = document.createElement('p');
      error.className = 'clancy-error small mb-0 mt-2';
      error.textContent = proposal.error_text;
      card.appendChild(error);
    }
    if (proposal.status === 'pending_approval') {
      card.appendChild(renderApprovalActions('proposal', proposal.id, 'Approve'));
    }
    return card;
  }

  function renderMemorySuggestion(suggestion) {
    const payload = suggestion.proposed_item_json || {};
    const card = document.createElement('div');
    card.className = 'clancy-agent-card';
    const header = document.createElement('div');
    header.className = 'd-flex justify-content-between align-items-start gap-2';
    const title = document.createElement('h3');
    title.textContent = payload.title || 'Family memory suggestion';
    const status = document.createElement('span');
    status.className = `clancy-status-pill${suggestion.status === 'pending_approval' ? ' pending' : ''}`;
    status.textContent = formatStatus(suggestion.status);
    header.append(title, status);
    card.appendChild(header);

    if (payload.body) {
      const body = document.createElement('p');
      body.className = 'text-muted mb-0';
      body.textContent = payload.body;
      card.appendChild(body);
    }
    if (suggestion.status === 'pending_approval') {
      card.appendChild(renderApprovalActions('memory', suggestion.id, 'Save'));
    }
    return card;
  }

  function renderApprovalActions(kind, id, approveLabel) {
    const actions = document.createElement('div');
    actions.className = 'clancy-card-actions';
    const reject = document.createElement('button');
    reject.type = 'button';
    reject.className = 'btn btn-outline-secondary btn-sm';
    reject.dataset.agentAction = kind;
    reject.dataset.agentId = id;
    reject.dataset.agentVerb = 'reject';
    reject.textContent = 'Reject';
    const approve = document.createElement('button');
    approve.type = 'button';
    approve.className = 'btn btn-primary btn-sm';
    approve.dataset.agentAction = kind;
    approve.dataset.agentId = id;
    approve.dataset.agentVerb = 'approve';
    approve.textContent = approveLabel;
    actions.append(reject, approve);
    return actions;
  }

  function handleImageSelection(event) {
    const files = Array.from(event.target.files || []);
    if (files.length > 4) {
      state.selectedFiles = [];
      event.target.value = '';
      setStatus('You can attach up to 4 images.');
    } else {
      state.selectedFiles = files;
      setStatus('');
    }
    renderSelectedImages();
  }

  function renderSelectedImages() {
    if (!elements.selectedImages) {
      return;
    }
    elements.selectedImages.replaceChildren();
    state.selectedFiles.forEach((file) => {
      const chip = document.createElement('div');
      chip.className = 'clancy-selected-image';
      const icon = document.createElement('i');
      icon.className = 'bi bi-image';
      icon.setAttribute('aria-hidden', 'true');
      const label = document.createElement('span');
      label.textContent = file.name;
      chip.append(icon, label);
      elements.selectedImages.appendChild(chip);
    });
  }

  function setComposerEnabled(enabled) {
    [elements.input, elements.imageInput].forEach((element) => {
      if (element) {
        element.disabled = !enabled;
      }
    });
    const sendButton = elements.composer?.querySelector('button[type="submit"]');
    if (sendButton) {
      sendButton.disabled = !enabled;
    }
  }

  function schedulePollingIfNeeded() {
    if (state.pollingTimer) {
      window.clearTimeout(state.pollingTimer);
      state.pollingTimer = null;
    }
    if (!hasPendingResponse()) {
      return;
    }
    state.pollingTimer = window.setTimeout(() => {
      void loadMessages();
    }, 2200);
  }

  function hasPendingResponse() {
    return state.messages.some((message) => {
      const runStatus = (message.run_status || '').toUpperCase();
      const messageStatus = (message.status || '').toUpperCase();
