    input: document.getElementById('clancy-message-input'),
    imageInput: document.getElementById('clancy-image-input'),
    selectedImages: document.getElementById('clancy-selected-images'),
  };

  renderStarters();
  bindEvents();
  void initialize();

  async function initialize() {
    setStatus(`Loading ${helperName}...`);
    try {
      await loadThreads();
      setStatus('');
    } catch (error) {
      showError(error);
    }
  }

  function bindEvents() {
    elements.newThread?.addEventListener('click', () => void createThread());
    elements.renameThread?.addEventListener('click', () => void renameActiveThread());
    elements.archiveThread?.addEventListener('click', () => void archiveActiveThread());
    elements.composer?.addEventListener('submit', (event) => {
      event.preventDefault();
      void sendMessage();
    });
    elements.input?.addEventListener('keydown', (event) => {
      if (event.key !== 'Enter') return;
      if (event.shiftKey) return;
      if (event.isComposing) return;
      event.preventDefault();
      void sendMessage();
    });
    elements.input?.addEventListener('input', resizeComposer);
    elements.imageInput?.addEventListener('change', handleImageSelection);
    elements.threadList?.addEventListener('click', (event) => {
      const button = event.target.closest('[data-thread-id]');
      if (!button) {
        return;
      }
      void selectThread(button.dataset.threadId);
    });
    elements.starters?.addEventListener('click', (event) => {
      const button = event.target.closest('[data-starter-index]');
      if (!button) {
        return;
      }
      const starter = starterPrompts[Number(button.dataset.starterIndex)];
      if (!starter || !elements.input) {
        return;
      }
      elements.input.value = starter.prompt || '';
      state.pendingContext = starter.context || {};
      elements.input.focus();
      resizeComposer();
    });
    elements.messages?.addEventListener('click', (event) => {
      const actionButton = event.target.closest('[data-agent-action]');
      if (actionButton) {
        void runCardAction(actionButton);
        return;
      }
      const suggestionButton = event.target.closest('[data-suggestion-prompt]');
      if (suggestionButton && elements.input) {
        elements.input.value = suggestionButton.dataset.suggestionPrompt || '';
        elements.input.focus();
        resizeComposer();
      }
    });
  }

  function apiRequest(path, options) {
    return sharedApiRequest(path, options, csrfToken);
  }

  async function loadThreads(preferredThreadId) {
    const threads = await apiRequest('/api/family-agent/threads/');
    state.threads = Array.isArray(threads) ? threads : [];
    const nextThreadId = preferredThreadId || state.activeThreadId || state.threads[0]?.id || null;
    renderThreads();

    if (nextThreadId) {
      await selectThread(nextThreadId, { skipThreadRender: true });
    } else {
      state.activeThreadId = null;
      state.messages = [];
      renderMessages();
    }
  }

  async function createThread() {
    setStatus('Starting a new conversation...');
    try {
      const thread = await apiRequest('/api/family-agent/threads/', {
        method: 'POST',
        json: { title: 'New conversation' },
      });
      await loadThreads(thread.id);
      setStatus('');
    } catch (error) {
      showError(error);
    }
  }

  async function selectThread(threadId, options) {
    if (!threadId) {
      return;
    }
    state.activeThreadId = threadId;
    if (!options?.skipThreadRender) {
      renderThreads();
    }
    updateActiveTitle();
    setStatus('Loading messages...');
    try {
      await loadMessages();
      setStatus('');
    } catch (error) {
      showError(error);
    }
  }

  async function loadMessages() {
    if (!state.activeThreadId) {
      return;
    }
    const query = new URLSearchParams({ thread_id: state.activeThreadId });
    const payload = await apiRequest(`/api/family-agent/thread/messages/?${query.toString()}`);
    const results = Array.isArray(payload?.results) ? payload.results : [];
    state.messages = results.slice().reverse();
    renderMessages();
    schedulePollingIfNeeded();
  }

  async function renameActiveThread() {
    const thread = getActiveThread();
    if (!thread) {
      return;
    }
    const title = window.prompt('Rename conversation', thread.title || 'New conversation');
    if (title === null) {
      return;
    }
    const trimmed = title.trim();
    if (!trimmed) {
      setStatus('Conversation title cannot be empty.');
      return;
    }

    setStatus('Renaming conversation...');
    try {
      await apiRequest(`/api/family-agent/threads/${thread.id}/`, {
        method: 'PATCH',
        json: { title: trimmed },
      });
      await loadThreads(thread.id);
      setStatus('');
    } catch (error) {
      showError(error);
    }
  }

  async function archiveActiveThread() {
    const thread = getActiveThread();
    if (!thread) {
      return;
    }
    if (!window.confirm(`Archive "${thread.title || 'this conversation'}"?`)) {
      return;
    }

    setStatus('Archiving conversation...');
    try {
      await apiRequest(`/api/family-agent/threads/${thread.id}/archive/`, {
        method: 'POST',
        json: {},
      });
      state.activeThreadId = null;
      await loadThreads();
      setStatus('');
    } catch (error) {
      showError(error);
    }
  }

  async function sendMessage() {
    if (state.isSending) {
      return;
    }
    const text = (elements.input?.value || '').trim();
    if (!text && state.selectedFiles.length === 0) {
      return;
    }

    state.isSending = true;
    setComposerEnabled(false);
    setStatus(`${helperName} is getting this ready...`);

    try {
      if (!state.activeThreadId) {
        const thread = await apiRequest('/api/family-agent/threads/', {
          method: 'POST',
          json: { title: 'New conversation' },
        });
        state.activeThreadId = thread.id;
      }

      const formData = new FormData();
      formData.append('thread_id', state.activeThreadId);
      formData.append('text', text);
      formData.append('context', JSON.stringify(buildMessageContext()));
      state.selectedFiles.forEach((file) => formData.append('images', file));

      const response = await apiRequest('/api/family-agent/thread/messages/', {
        method: 'POST',
        body: formData,
      });

      if (elements.input) {
        elements.input.value = '';
      }
      if (elements.imageInput) {
        elements.imageInput.value = '';
      }
      state.selectedFiles = [];
      state.pendingContext = {};
      renderSelectedImages();
      resizeComposer();
      await loadThreads(response?.thread?.id || state.activeThreadId);
      setStatus('');
    } catch (error) {
      showError(error);
    } finally {
      state.isSending = false;
      setComposerEnabled(true);
    }
  }

  function buildMessageContext() {
    return {
      ...baseContext,
      ...state.pendingContext,
      google_maps_widget_supported: true,
    };
  }

  async function runCardAction(button) {
    const kind = button.dataset.agentAction;
    const id = button.dataset.agentId;
    const verb = button.dataset.agentVerb;
    if (!kind || !id || !verb) {
      return;
    }

    const path = kind === 'proposal'
      ? `/api/family-agent/proposals/${id}/${verb}/`
      : `/api/family-agent/memory-suggestions/${id}/${verb}/`;

    button.disabled = true;
    setStatus(verb === 'approve' ? 'Approving...' : 'Rejecting...');
    try {
      await apiRequest(path, { method: 'POST', json: {} });
      await loadMessages();
      setStatus('');
    } catch (error) {
      button.disabled = false;
      showError(error);
    }
  }

  function renderStarters() {
    if (!elements.starters) {
      return;
    }
    elements.starters.replaceChildren();
    starterPrompts.forEach((starter, index) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'btn btn-outline-primary btn-sm clancy-starter';
      button.dataset.starterIndex = String(index);
      const icon = document.createElement('i');
      icon.className = `bi ${starter.icon || 'bi-stars'} me-1`;
      icon.setAttribute('aria-hidden', 'true');
      button.append(icon, document.createTextNode(starter.label || starter.prompt || 'Start'));
      elements.starters.appendChild(button);
    });
  }

  function renderThreads() {
    if (!elements.threadList) {
      return;
    }
    elements.threadList.replaceChildren();
    if (state.threads.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'text-muted text-center py-4';
      empty.textContent = 'No conversations yet';
      elements.threadList.appendChild(empty);
      return;
    }
    state.threads.forEach((thread) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = `clancy-thread-item${thread.id === state.activeThreadId ? ' active' : ''}`;
      button.dataset.threadId = thread.id;
      const title = document.createElement('span');
      title.className = 'clancy-thread-title';
      title.textContent = thread.title || 'New conversation';
      const meta = document.createElement('span');
      meta.className = 'clancy-thread-meta';
      meta.textContent = formatDate(thread.updated_at);
      button.append(title, meta);
      elements.threadList.appendChild(button);
