function normalizePlaceLinks(grounding, rawText) {
  const places = (grounding && Array.isArray(grounding.places)) ? grounding.places : [];
  if (places.length === 0) return [];
  const supports = (grounding && Array.isArray(grounding.supports)) ? grounding.supports : [];
  const lowerText = String(rawText || '').toLowerCase();
  let gate = null;
  if (supports.length > 0) {
    gate = new Set();
    supports.forEach((support) => {
      const segment = String((support && support.segment_text) || '').trim().toLowerCase();
      if (!segment || !lowerText.includes(segment)) return;
      const ids = Array.isArray(support && support.place_ids) ? support.place_ids : [];
      ids.forEach((id) => {
        if (id) gate.add(String(id));
      });
    });
    if (gate.size === 0) gate = null;
  }
  return places
    .map((place) => {
      const label = String((place && place.name) || '').trim();
      const url = String((place && place.url) || '').trim();
      const placeId = String((place && place.place_id) || '').trim();
      if (!label || !url) return null;
      if (gate && (!placeId || !gate.has(placeId))) return null;
      return { label, labelLower: label.toLowerCase(), url, placeId };
    })
    .filter(Boolean)
    .sort((a, b) => b.label.length - a.label.length);
}

