    appendMessage({ role: 'user', text });
    input.value = '';
    resizeInput();
    updateFullLink();

    try {
      const threadId = await ensureThread();
      const response = await apiRequest('/api/family-agent/thread/messages/', {
        method: 'POST',
        json: {
            thread_id: threadId,
            text,
            context: {
              ...contextPayload,
              google_maps_widget_supported: true,
            },
          },
        });
      const newThreadId = response?.thread?.id || threadId;
      const splitOccurred = Boolean(response?.split_occurred);
      if (splitOccurred && newThreadId !== threadId) {
        appendSplitNotice();
      }
      state.threadId = newThreadId;
      state.threadsLoaded = false;
      updateTokenPressureBanner(response?.token_pressure || response?.thread?.token_pressure || 'ok');
      await loadMessages();
      schedulePolling();
    } catch (error) {
      appendMessage({ role: 'assistant', text: error.message || 'Something went wrong.' });
      setStatus('');
    } finally {
      state.isSending = false;
    }
  }

  async function loadMessages() {
    if (!state.threadId) {
      return;
    }
    const query = new URLSearchParams({ thread_id: state.threadId });
    const payload = await apiRequest(`/api/family-agent/thread/messages/?${query.toString()}`);
    const results = Array.isArray(payload?.results) ? payload.results.slice().reverse() : [];
    renderMessages(results);
    if (!hasPendingResponse(results)) {
      setStatus('');
      clearPolling();
    }
  }

  function schedulePolling() {
    clearPolling();
    state.pollAttempts = 0;
    state.pollingTimer = window.setInterval(() => {
      if (document.visibilityState === 'hidden') {
        return;
      }
      state.pollAttempts += 1;
      if (state.pollAttempts > POLL_MAX_ATTEMPTS) {
        clearPolling();
        setStatus('');
        return;
      }
      void loadMessages().catch((error) => {
        setStatus(error.message || 'Could not refresh the conversation.');
        clearPolling();
      });
    }, POLL_INTERVAL_MS);
  }

  function clearPolling() {
    if (state.pollingTimer) {
      window.clearInterval(state.pollingTimer);
      state.pollingTimer = null;
    }
    state.pollAttempts = 0;
  }

  function updateTokenPressureBanner(level) {
    const host = document.getElementById('clancy-assistant-token-banner');
    if (!host) {
      return;
    }
    if (level === 'warning') {
      host.hidden = false;
      host.className = 'clancy-assistant-token-banner clancy-assistant-token-banner-warning';
      host.textContent = 'This conversation is getting long — I’ll start a fresh one soon to keep things snappy.';
    } else if (level === 'critical') {
      host.hidden = false;
      host.className = 'clancy-assistant-token-banner clancy-assistant-token-banner-critical';
      host.textContent = 'Conversation is full. Starting a new thread on your next message.';
    } else {
      host.hidden = true;
      host.textContent = '';
    }
  }

  function appendSplitNotice() {
    if (!messages) {
      return;
    }
    const chip = document.createElement('div');
    chip.className = 'clancy-assistant-split-chip';
    chip.textContent = 'Continuing in a new conversation';
    messages.appendChild(chip);
    messages.scrollTop = messages.scrollHeight;
  }

  async function runCardAction(button) {
    const kind = button.dataset.clancyCardAction;
    const id = button.dataset.clancyCardId;
    const verb = button.dataset.clancyCardVerb;
    if (!kind || !id || !verb) {
      return;
    }

    const path = kind === 'memory'
      ? `/api/family-agent/memory-suggestions/${id}/${verb}/`
      : `/api/family-agent/proposals/${id}/${verb}/`;

    button.disabled = true;
    setStatus(verb === 'approve' ? 'Approving...' : 'Rejecting...');
    try {
      await apiRequest(path, { method: 'POST', json: {} });
      await loadMessages();
      setStatus('');
    } catch (error) {
      button.disabled = false;
      setStatus(error.message || 'Could not update the suggestion.');
    }
  }

  function renderEmptyState() {
    if (!messages) {
      return;
    }
    messages.replaceChildren();
    const empty = document.createElement('p');
    empty.className = 'clancy-assistant-empty';
    empty.textContent = `Ask ${helperName} for quick help, or open the full conversation when you need more room.`;
    messages.appendChild(empty);

    if (defaultPrompt.trim()) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'clancy-assistant-prompt-card';
      button.dataset.clancySuggestionPrompt = defaultPrompt;

      const label = document.createElement('span');
      label.className = 'clancy-assistant-prompt-card-label';
      label.textContent = 'Suggested prompt';

      const prompt = document.createElement('span');
      prompt.className = 'clancy-assistant-prompt-card-text';
      prompt.textContent = defaultPrompt;

      button.append(label, prompt);
      messages.appendChild(button);
    }
  }

  function renderMessages(items) {
    if (!messages) {
      return;
    }
    messages.replaceChildren();
    if (!items.length) {
      renderEmptyState();
      return;
    }
    items.slice(-8).forEach((message) => appendMessage(message));
    messages.scrollTop = messages.scrollHeight;
  }

  function appendMessage(message) {
    if (!messages) {
      return;
    }
    if (message.role === 'system') {
      return;
    }
    const empty = messages.querySelector('.clancy-assistant-empty');
    empty?.remove();
    const wrapper = document.createElement('div');
    wrapper.className = `clancy-assistant-message ${message.role || 'assistant'}`;
    const bubble = document.createElement('div');
    bubble.className = 'clancy-assistant-bubble';
    const text = document.createElement('div');
    text.className = 'clancy-assistant-message-text';
    const entityLinks = Array.isArray(message.entity_links) ? message.entity_links : [];
    const grounding = (message.context_json && message.context_json.google_maps_grounding) || {};
    if (message.role === 'assistant' || message.role === 'system') {
      renderFormattedMessageText(text, message.text || '', entityLinks, grounding);
    } else {
      text.textContent = message.text || '';
    }
    bubble.appendChild(text);
    wrapper.appendChild(bubble);

    const cards = document.createElement('div');
    cards.className = 'clancy-assistant-card-stack';
    renderRunError(message, cards);
    renderCitations(message.citations_json || [], cards, message.context_json || {});
    (message.action_suggestions || []).forEach((suggestion) => cards.appendChild(renderActionSuggestion(suggestion)));
    renderGoogleMapsGroundingWidget(message.context_json || {}, cards, {
      apiKey: googleMapsClientApiKey,
      cardClassName: 'clancy-assistant-card clancy-assistant-google-maps-widget',
      labelClassName: 'clancy-assistant-card-label',
      hostClassName: 'clancy-assistant-google-maps-widget-host',
      widgetClassName: 'clancy-assistant-google-maps-contextual',
    });
    (message.proposals || []).forEach((proposal) => cards.appendChild(renderProposal(proposal)));
    (message.memory_suggestions || []).forEach((suggestion) => cards.appendChild(renderMemorySuggestion(suggestion)));
    if (cards.childElementCount > 0) {
      wrapper.appendChild(cards);
    }

    messages.appendChild(wrapper);
    messages.scrollTop = messages.scrollHeight;
  }

  function hasPendingResponse(items) {
    return items.some((message) => {
      const runStatus = message.run_status || message.status;
      return runStatus && !['COMPLETED', 'FAILED'].includes(String(runStatus).toUpperCase());
    });
  }

  function setStatus(value) {
    if (status) {
      status.textContent = value || '';
    }
  }

  function resizeInput() {
    if (!input) {
      return;
    }
    input.style.height = 'auto';
    input.style.height = `${Math.min(input.scrollHeight, 144)}px`;
  }

  function renderFormattedMessageText(container, value, entityLinks, grounding) {
    const rawText = String(value || '').trim();
    if (!rawText) {
      return;
    }

    const links = normalizeEntityLinks(entityLinks);
    const placeLinks = normalizePlaceLinks(grounding, rawText);
    const lines = rawText.split(/\r?\n/);
    let paragraphLines = [];
    let list = null;

    function flushParagraph() {
      if (paragraphLines.length === 0) {
        return;
      }
      const paragraph = document.createElement('p');
      appendInlineMarkdown(paragraph, paragraphLines.join(' '), links, placeLinks);
      container.appendChild(paragraph);
      paragraphLines = [];
    }

    function flushList() {
      if (!list) {
        return;
      }
      container.appendChild(list);
      list = null;
    }

    lines.forEach((line) => {
      const trimmed = line.trim();
      if (!trimmed) {
        flushParagraph();
        flushList();
        return;
      }

      const headingMatch = trimmed.match(/^(#{1,6})\s+(.+?)\s*#*$/);
      if (headingMatch) {
        flushParagraph();
        flushList();
        const level = Math.min(headingMatch[1].length, 6);
        const heading = document.createElement(`h${level}`);
        appendInlineMarkdown(heading, headingMatch[2], links, placeLinks);
        container.appendChild(heading);
        return;
      }

      const unorderedMatch = trimmed.match(/^[-*]\s+(.+)$/);
      const orderedMatch = trimmed.match(/^\d+\.\s+(.+)$/);
      if (unorderedMatch || orderedMatch) {
        flushParagraph();
        const nextTag = unorderedMatch ? 'ul' : 'ol';
        if (!list || list.tagName.toLowerCase() !== nextTag) {
          flushList();
          list = document.createElement(nextTag);
        }
        const item = document.createElement('li');
        appendInlineMarkdown(item, unorderedMatch?.[1] || orderedMatch?.[1] || '', links, placeLinks);
        list.appendChild(item);
        return;
      }

      flushList();
      paragraphLines.push(trimmed);
    });

    flushParagraph();
    flushList();
  }

  function appendInlineMarkdown(parent, value, entityLinks, placeLinks) {
    const text = String(value || '');
    const places = Array.isArray(placeLinks) ? placeLinks : [];
    const pattern = /(\[\[ref:\d+\]\]|\*\*[^*]+\*\*|__[^_]+__|`[^`]+`)/g;
    let cursor = 0;
    text.replace(pattern, (match, _token, offset) => {
      if (offset > cursor) {
        appendLinkedText(parent, text.slice(cursor, offset), entityLinks, places);
      }
      const refMatch = match.match(/^\[\[ref:(\d+)\]\]$/);
      if (refMatch) {
        const refIndex = Number(refMatch[1]);
        const link = entityLinks[refIndex];
        if (link) {
          parent.appendChild(renderInlineEntityCard(link));
        }
      } else if (match.startsWith('`')) {
        const code = document.createElement('code');
        appendLinkedText(code, match.slice(1, -1), entityLinks, places);
        parent.appendChild(code);
      } else {
        const strong = document.createElement('strong');
        appendLinkedText(strong, match.slice(2, -2), entityLinks, places);
        parent.appendChild(strong);
      }
      cursor = offset + match.length;
      return match;
    });
    if (cursor < text.length) {
      appendLinkedText(parent, text.slice(cursor), entityLinks, places);
    }
  }

  function renderInlineEntityCard(link) {
    const anchor = document.createElement('a');
    anchor.className = `clancy-assistant-entity-card clancy-assistant-entity-card--${link.kind || 'generic'}`;
    anchor.href = link.url;
    if (link.ownerName) {
      anchor.title = `${link.label} (${link.ownerName})`;
    }
    if (link.kind === 'event' && (link.ownerAvatarUrl || link.ownerInitials || link.ownerName)) {
      if (link.ownerAvatarUrl) {
        const avatar = document.createElement('img');
        avatar.className = 'clancy-assistant-entity-card__avatar';
        avatar.src = link.ownerAvatarUrl;
        avatar.alt = link.ownerName || link.label;
        anchor.appendChild(avatar);
      } else {
        const initials = document.createElement('span');
        initials.className = 'clancy-assistant-entity-card__initials';
        initials.textContent = link.ownerInitials || initialsFromName(link.ownerName || link.label);
        if (link.color) {
          initials.style.backgroundColor = link.color;
        }
        anchor.appendChild(initials);
      }
    }
    const kindChip = document.createElement('span');
    kindChip.className = 'clancy-assistant-entity-card__kind';
    kindChip.textContent = humanizeKind(link.kind);
    const labelSpan = document.createElement('span');
    labelSpan.className = 'clancy-assistant-entity-card__label';
    labelSpan.textContent = link.label;
    anchor.appendChild(kindChip);
    anchor.appendChild(labelSpan);
    return anchor;
  }

  function initialsFromName(value) {
    const parts = String(value || '').trim().split(/\s+/).filter(Boolean);
    if (parts.length === 0) {
      return '?';
    }
    if (parts.length === 1) {
      return parts[0].slice(0, 1).toUpperCase();
    }
    return `${parts[0].slice(0, 1)}${parts[parts.length - 1].slice(0, 1)}`.toUpperCase();
  }

  function humanizeKind(kind) {
    if (!kind) {
      return 'Link';
    }
    return String(kind)
      .replace(/_/g, ' ')
      .replace(/\b\w/g, (c) => c.toUpperCase());
  }

  function appendLinkedText(parent, value, entityLinks, placeLinks) {
    const text = String(value || '');
    const places = Array.isArray(placeLinks) ? placeLinks : [];
    if (!text || (entityLinks.length === 0 && places.length === 0)) {
      parent.appendChild(document.createTextNode(text));
      return;
    }

    const lowerText = text.toLowerCase();
    const wordChar = /[A-Za-z0-9_]/;
    let cursor = 0;
    while (cursor < text.length) {
      let bestMatch = null;
      const consider = (index, link, kind) => {
        const length = link.label.length;
        if (
          bestMatch === null
          || index < bestMatch.index
          || (index === bestMatch.index && length > bestMatch.link.label.length)
        ) {
          bestMatch = { index, link, kind };
        }
      };
      entityLinks.forEach((link) => {
        const index = lowerText.indexOf(link.labelLower, cursor);
        if (index === -1) return;
        consider(index, link, 'entity');
      });
      places.forEach((link) => {
        const index = lowerText.indexOf(link.labelLower, cursor);
        if (index === -1) return;
        const before = index > 0 ? text[index - 1] : '';
        const after = text[index + link.label.length] || '';
        if (wordChar.test(before) || wordChar.test(after)) return;
        consider(index, link, 'place');
      });

      if (bestMatch === null) {
        parent.appendChild(document.createTextNode(text.slice(cursor)));
        break;
      }

      if (bestMatch.index > cursor) {
        parent.appendChild(document.createTextNode(text.slice(cursor, bestMatch.index)));
      }
      const anchor = document.createElement('a');
      anchor.href = bestMatch.link.url;
      anchor.textContent = text.slice(bestMatch.index, bestMatch.index + bestMatch.link.label.length);
      if (bestMatch.kind === 'place') {
        anchor.className = 'clancy-assistant-place-link';
        anchor.target = '_blank';
        anchor.rel = 'noopener noreferrer';
      } else {
        anchor.className = 'clancy-assistant-entity-link';
      }
      parent.appendChild(anchor);
      cursor = bestMatch.index + bestMatch.link.label.length;
    }
  }

  function normalizeEntityLinks(value) {
    if (!Array.isArray(value)) {
      return [];
    }
    return value
      .filter((item) => item && item.label && item.url)
      .map((item) => {
        const label = String(item.label);
        return {
          kind: String(item.kind || ''),
          id: String(item.id || ''),
          label,
          labelLower: label.toLowerCase(),
          url: String(item.url),
          ownerName: String(item.owner_name || ''),
          ownerShortName: String(item.owner_short_name || ''),
          ownerInitials: String(item.owner_initials || ''),
          ownerAvatarUrl: String(item.owner_avatar_url || ''),
          color: String(item.color || ''),
        };
      });
  }

  function renderRunError(message, cards) {
    if ((message.run_status || '').toUpperCase() !== 'FAILED' || !message.run_error_text) {
      return;
    }
    const card = document.createElement('div');
    card.className = 'clancy-assistant-card clancy-assistant-error-card';
    card.textContent = message.run_error_text;
    cards.appendChild(card);
  }

  function renderCitations(citations, cards, contextJson) {
    if (contextJson?.google_maps_grounding?.widget_context_tokens?.length) {
      return;
    }
    if (!Array.isArray(citations) || citations.length === 0) {
      return;
    }
    const card = document.createElement('div');
    card.className = 'clancy-assistant-card clancy-assistant-citations';
    const label = document.createElement('div');
    label.className = 'clancy-assistant-card-label';
    label.textContent = 'Sources';
    card.appendChild(label);
    citations.forEach((citation) => {
      if (!citation.url) {
        return;
      }
      const link = document.createElement('a');
      link.className = 'clancy-assistant-citation';
      link.href = citation.url;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.textContent = citation.title || citation.url;
      card.appendChild(link);
    });
    if (card.childElementCount > 1) {
      cards.appendChild(card);
    }
  }

  function renderActionSuggestion(suggestion) {
    const card = document.createElement('div');
    card.className = 'clancy-assistant-card clancy-assistant-action-card';
    const label = document.createElement('div');
    label.className = 'clancy-assistant-card-label';
    label.textContent = suggestion.label || 'Suggested action';
    const title = document.createElement('h3');
    title.className = 'clancy-assistant-card-title';
    title.textContent = suggestion.title || 'Suggestion';
    card.append(label, title);

    if (suggestion.summary) {
      const summary = document.createElement('p');
      summary.className = 'clancy-assistant-card-copy';
      summary.textContent = suggestion.summary;
      card.appendChild(summary);
    }

    const target = getActionSuggestionTarget(suggestion);
    if (target.supportingText) {
      const supporting = document.createElement('p');
      supporting.className = 'clancy-assistant-card-meta';
      supporting.textContent = target.supportingText;
      card.appendChild(supporting);
    }
    if (target.imageUrl) {
      const image = document.createElement('img');
      image.src = target.imageUrl;
      image.alt = suggestion.product?.image_alt || suggestion.title || 'Suggestion image';
      image.className = 'clancy-assistant-card-image';
      card.appendChild(image);
    }

    const actions = document.createElement('div');
    actions.className = 'clancy-assistant-card-actions';
    if (target.url) {
      const link = document.createElement('a');
      link.href = target.url;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.className = 'btn btn-primary btn-sm';
      link.textContent = target.buttonLabel;
      actions.appendChild(link);
    }
    if (suggestion.prompt) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'btn btn-outline-primary btn-sm';
      button.dataset.clancySuggestionPrompt = suggestion.prompt;
      button.textContent = 'Ask about this';
      actions.appendChild(button);
    }
    if (actions.childElementCount > 0) {
      card.appendChild(actions);
    }
    return card;
  }

  function getActionSuggestionTarget(suggestion) {
    if (suggestion.restaurant?.maps_url) {
      return {
        url: suggestion.restaurant.maps_url,
        buttonLabel: 'Open in Maps',
        supportingText: suggestion.restaurant.address || suggestion.restaurant.name || '',
      };
    }
    if (suggestion.url) {
      return {
        url: suggestion.url,
        buttonLabel: suggestion.type === 'external_scheduling_handoff' ? 'Open Calendly' : 'Open',
        supportingText: '',
      };
    }
    if (suggestion.product?.url) {
      const merchant = [suggestion.product.merchant_name, suggestion.product.merchant_domain]
        .filter(Boolean)
        .join(' / ');
      return {
        url: suggestion.product.url,
        buttonLabel: 'Open Product',
        supportingText: [merchant, suggestion.product.price_text, suggestion.product.availability_text]
          .filter(Boolean)
          .join(' - '),
        imageUrl: suggestion.product.image_url || '',
      };
    }
    return { url: '', buttonLabel: 'Open', supportingText: '' };
  }

  function renderProposal(proposal) {
    const card = document.createElement('div');
    card.className = 'clancy-assistant-card';
    const header = document.createElement('div');
    header.className = 'clancy-assistant-card-header';
    const title = document.createElement('h3');
    title.className = 'clancy-assistant-card-title';
    title.textContent = proposal.summary || 'Proposal';
    const statusBadge = document.createElement('span');
    statusBadge.className = `clancy-assistant-status-pill${proposal.status === 'pending_approval' ? ' pending' : ''}`;
    statusBadge.textContent = formatStatus(proposal.status);
    header.append(title, statusBadge);
    card.appendChild(header);

    if (proposal.preview_text) {
      const preview = document.createElement('p');
      preview.className = 'clancy-assistant-card-copy';
      preview.textContent = proposal.preview_text;
      card.appendChild(preview);
    }
    if (proposal.error_text) {
      const error = document.createElement('p');
      error.className = 'clancy-assistant-card-error';
      error.textContent = proposal.error_text;
      card.appendChild(error);
    }
    if (proposal.status === 'pending_approval') {
      card.appendChild(renderApprovalActions('proposal', proposal.id, 'Approve'));
    }
    return card;
  }

  function renderMemorySuggestion(suggestion) {
    const payload = suggestion.proposed_item_json || {};
    const card = document.createElement('div');
    card.className = 'clancy-assistant-card clancy-assistant-memory-card';
    const header = document.createElement('div');
    header.className = 'clancy-assistant-card-header';
    const title = document.createElement('h3');
    title.className = 'clancy-assistant-card-title';
    title.textContent = payload.title || 'Family memory suggestion';
    const statusBadge = document.createElement('span');
    statusBadge.className = `clancy-assistant-status-pill${suggestion.status === 'pending_approval' ? ' pending' : ''}`;
    statusBadge.textContent = formatStatus(suggestion.status);
    header.append(title, statusBadge);
    card.appendChild(header);

    if (payload.body) {
      const body = document.createElement('p');
      body.className = 'clancy-assistant-card-copy';
      body.textContent = payload.body;
      card.appendChild(body);
    }
    if (suggestion.status === 'pending_approval') {
      card.appendChild(renderApprovalActions('memory', suggestion.id, 'Save'));
    }
    return card;
  }

  function renderApprovalActions(kind, id, approveLabel) {
    const actions = document.createElement('div');
    actions.className = 'clancy-assistant-card-actions';
    actions.append(
      buildCardActionButton(kind, id, 'reject', 'Reject'),
      buildCardActionButton(kind, id, 'approve', approveLabel)
    );
    return actions;
  }

  function buildCardActionButton(kind, id, verb, label) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = verb === 'approve' ? 'btn btn-primary btn-sm' : 'btn btn-outline-secondary btn-sm';
    button.dataset.clancyCardAction = kind;
    button.dataset.clancyCardId = id;
    button.dataset.clancyCardVerb = verb;
    button.textContent = label;
    return button;
  }

  function formatStatus(value) {
    return String(value || '')
      .replace(/_/g, ' ')
      .replace(/\b\w/g, (letter) => letter.toUpperCase());
  }

  function updateFullLink() {
    if (!fullLink) {
      return;
    }
    const url = new URL(fullUrl, window.location.origin);
    Object.entries(contextPayload || {}).forEach(([key, value]) => {
      if (value !== null && value !== undefined && typeof value !== 'object') {
        url.searchParams.set(key, String(value));
      }
    });
    const prompt = input?.value.trim() || defaultPrompt;
    if (prompt) {
      url.searchParams.set('prompt', prompt);
    }
    fullLink.href = `${url.pathname}${url.search}`;
